#!/usr/bin/env python3
"""Build the complete static portfolio. Run from any directory: python3 redesign/build.py."""
from pathlib import Path
from html import escape as e
import json, shutil, os
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'dist'
DATA=json.loads((ROOT/'redesign/projects.json').read_text())
BASE=os.environ.get('PORTFOLIO_URL','https://lucasjmgeurts-jpg.github.io/max-website/').rstrip('/')+'/'
EMAIL='m.t.j.geurts@gmail.com'

def tags(p):return ''.join(f'<span class="tag">{e(t)}</span>' for t in p['tech'])
def visual(p):
 kind=p['id']
 if kind=='financial-dashboard':return '''<div class="project-visual"><div class="visual-label">FINANCIAL OPERATIONS <span>Illustration · fictional data</span></div><div class="mini-dash"><div class="windowbar"><i></i><i></i><i></i></div><header>Subscription overview <small>MONTHLY</small></header><div class="stat-grid"><div class="stat"><small>Recurring income</small><b>€ 12,480</b></div><div class="stat"><small>Needs attention</small><b>03</b></div></div><div class="bar-chart" aria-hidden="true"><i style="height:30%"></i><i style="height:42%"></i><i style="height:36%"></i><i style="height:62%"></i><i style="height:55%"></i><i style="height:72%"></i><i style="height:64%"></i><i style="height:90%"></i><i style="height:79%"></i><i style="height:100%"></i></div><div class="dash-foot"><span>PAYMENT RECORDS → BUSINESS RULES</span><span>→ CLEAR OVERVIEW</span></div></div></div>'''
 if kind=='ai-chat':return '''<div class="project-visual"><div class="visual-label">LOCAL AI + APPLICATION LOGIC <span>Illustrative conversation</span></div><div class="chat-bubble user">What was our subscription income in March?</div><div class="chat-bubble ai"><small>APPLICATION REPORT · FICTIONAL DATA</small><div class="data-row"><span>Period</span><b>March</b></div><div class="data-row"><span>Subscription income</span><b>€ 12,480</b></div><div class="data-row"><span>Records needing review</span><b>3</b></div></div><div class="dash-foot"><span>OLLAMA → STRUCTURED COMMAND</span><span>→ LARAVEL FUNCTION</span></div></div>'''
 if kind=='lead-generator':return '''<div class="project-visual"><div class="visual-label">RESEARCH → PROTOTYPE <span>Conceptual illustration</span></div><div class="pipeline"><div class="browser-mini"><div class="windowbar"><i></i><i></i><i></i></div><div class="line short"></div><div class="line"></div><div class="line"></div><div class="block"></div><small>Website input</small></div><span class="connector">→</span><div class="browser-mini after"><div class="windowbar"><i></i><i></i><i></i></div><div class="line short"></div><div class="line"></div><div class="block"></div><small>Multi-page prototype</small></div></div><div class="dash-foot" style="margin-top:20px"><span>EXTRACT / ANALYSE / GENERATE</span><span>HTML + ASSETS</span></div></div>'''
 return f'<div class="project-visual"><div class="eyebrow">{e(p["category"])}</div><div class="visual-title">{e(p["short"])}</div><div class="experience-tags">{tags(p)}</div></div>'

def page(path,title,description,body,active=''):
 depth=len(Path(path).parts)-1;r='../'*depth
 nav=''.join(f'<a href="{r}{url}"'+(' class="active" aria-current="page"' if name==active else '')+f'>{name}</a>' for name,url in [('Home','index.html'),('Projects','projects.html'),('About','about.html'),('Resume','resume.html')])
 canonical=BASE+path
 html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="dark"><title>{e(title)} | Max Geurts</title><meta name="description" content="{e(description,quote=True)}"><link rel="canonical" href="{canonical}"><meta property="og:title" content="{e(title,quote=True)} | Max Geurts"><meta property="og:description" content="{e(description,quote=True)}"><meta property="og:type" content="website"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{BASE}assets/social.png"><meta name="theme-color" content="#0B1220"><link rel="icon" href="{r}assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="{r}assets/style.css"><script src="{r}assets/main.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a><header class="header"><div class="container"><nav class="nav" aria-label="Main navigation"><a class="logo" href="{r}index.html" aria-label="Max Geurts home">MG<span>.</span></a><button class="menu" aria-expanded="false" aria-controls="navigation">Menu ☰</button><div id="navigation" class="nav-links">{nav}<a class="nav-contact{' active' if active=='Contact' else ''}" href="{r}contact.html">Let's talk <span aria-hidden="true">↗</span></a></div></nav></div></header><main id="main">{body}</main><footer class="footer"><div class="container footer-inner"><span>© 2026 Max Geurts</span><span>PHP & Laravel · AI integrations · Business automation</span><a href="{r}index.html">Back to home ↑</a></div></footer></body></html>'''
 # Page fragments use a root-relative placeholder for local assets/links.
 html=html.replace('@ROOT@',r)
 target=OUT/path;target.parent.mkdir(parents=True,exist_ok=True);target.write_text(html)

def contact():return f'''<section class="contact-section"><div class="container"><div class="eyebrow">Get in touch</div><h2 class="contact-heading">Let's build something useful.</h2><p>I'm interested in junior back-end and software development opportunities where I can contribute to real products, learn from experienced developers and grow with a team.</p><div class="contact-line"><a class="email" href="mailto:{EMAIL}">{EMAIL} ↗</a><div class="socials"><a href="https://github.com/Mexwwww">GitHub ↗</a><a href="@ROOT@cv/Max-Geurts-Software-Development-NL.pdf" download>Download CV ↓</a></div></div></div></section>'''

def project_row(p,i):return f'''<article class="project-row">{visual(p)}<div class="project-copy"><div class="number">0{i} / {e(p['category']).upper()}</div><h3><a href="@ROOT@{p['path']}">{e(p['title'])}</a></h3><p>{e(p['summary'])}</p><div class="experience-tags">{tags(p)}</div><a class="link" href="@ROOT@{p['path']}">Explore the case study <span aria-hidden="true">↗</span></a></div></article>'''

def game_card(p):return f'''<a class="game-card" href="@ROOT@{p['path']}"><img src="@ROOT@assets/{p['image']}" alt="Gameplay from {e(p['title'])}" width="600" height="375" loading="lazy"><h3>{e(p['title'])} ↗</h3><p>{e(p['short'])}</p></a>'''

OUT.mkdir(exist_ok=True);(OUT/'assets').mkdir(exist_ok=True)
for name in ['style.css','main.js']:shutil.copy2(ROOT/'redesign'/name,OUT/'assets'/name)
(OUT/'.nojekyll').touch()
(OUT/'assets/favicon.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="12" fill="#0b1220"/><text x="9" y="42" fill="#69d6c6" font-size="28" font-family="Arial" font-weight="bold">MG</text></svg>')
(OUT/'assets/social.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1200 630"><rect width="1200" height="630" fill="#0b1220"/><text x="90" y="230" font-size="100" fill="#f3f6fb" font-family="Arial">Max Geurts</text><text x="90" y="320" font-size="45" fill="#69d6c6" font-family="Arial">Junior Back-end Developer</text><text x="90" y="420" font-size="28" fill="#a7b4c6" font-family="Arial">PHP &amp; Laravel / AI Integrations / Business Automation</text></svg>')
hero='''<section class="hero"><div class="container"><div class="hero-top"><div class="eyebrow">Developer portfolio / 2026</div><div class="status">Open to junior opportunities</div></div><div class="hero-grid"><div><h1>Max Geurts<span style="color:var(--accent)">.</span></h1><div class="hero-role">Junior Back-end Developer</div><p class="hero-intro">Building web applications, business automation and AI integrations with <span style="color:var(--text)">PHP & Laravel.</span></p><div class="actions"><a class="btn primary" href="#work">View my work <span aria-hidden="true">↗</span></a><a class="btn" href="@ROOT@cv/Max-Geurts-Software-Development-NL.pdf" download>Download CV <span aria-hidden="true">↓</span></a></div><div class="hero-foot"><span>Based in the Netherlands</span><span>32 hours / week</span><a href="@ROOT@contact.html">Get in touch ↗</a></div></div><div class="system" role="img" aria-label="Conceptual overview: an interface connects to Laravel business logic, which works with a database, external APIs and local AI. This is not an exact project architecture."><div class="system-head"><span>Connecting the pieces</span><i>BACK-END DEVELOPMENT</i></div><div class="system-route"><div class="node"><strong>Interface</strong><small>Questions & actions</small></div><span class="connector">→</span><div class="node core"><strong>Laravel</strong><small>Application & business logic</small></div></div><div class="system-label">↓ &nbsp; TURNING DATA INTO SOMETHING USEFUL &nbsp; ↓</div><div class="system-output"><div class="node"><b>▤</b>Database</div><div class="node"><b>↔</b>External APIs</div><div class="node"><b>✳</b>Local AI</div></div><div class="system-bottom"><span>PHP / LARAVEL / SQL</span><span>Conceptual overview</span></div></div></div></div></section><div class="container"><div class="stack-line"><small>MY CORE TOOLKIT</small><span>PHP</span><span>Laravel</span><span>MySQL</span><span>REST APIs</span><span>Filament</span><span>Ollama</span></div></div>'''
experience='''<div class="container"><section class="experience" aria-labelledby="experience-title"><div><div class="eyebrow">Beyond the classroom</div><h2 id="experience-title">Real-world development<br>experience.</h2></div><div class="experience-main"><div class="experience-meta"><span>XEROPEX</span><span>2025 — 2026</span></div><p>During internships and paid development work, I built internal Laravel applications and contributed to existing customer software. From API integrations and payment logic to debugging and code reviews, I worked on software used in a professional setting.</p><div class="experience-tags"><span class="tag">Business applications</span><span class="tag">Internal automation</span><span class="tag">Team workflows</span></div></div></section></div>'''
featured='<section class="section" id="work"><div class="container"><div class="section-head"><div><div class="eyebrow">Selected work</div><h2>Practical problems.<br>Thoughtful software.</h2></div><p>A closer look at three business applications I developed at Xeropex.</p></div>'+''.join(project_row(p,i+1) for i,p in enumerate(DATA[:3]))+'<div style="text-align:right;margin-top:30px"><a class="link" href="@ROOT@projects.html">View all projects <span>↗</span></a></div></div></section>'
expertise='''<section class="section expertise"><div class="container"><div class="section-head"><div><div class="eyebrow">How I contribute</div><h2>A back-end mindset.</h2></div></div><div class="expertise-grid"><div class="expertise-item"><div class="symbol">{ }</div><h3>Back-end development</h3><p>Application logic, databases and API integrations. Building new functions and understanding how to maintain existing software.</p><small>PHP · Laravel · MySQL · Filament</small></div><div class="expertise-item"><div class="symbol">↔</div><h3>AI & automation</h3><p>Connecting local models to application functions, processing structured output and turning repetitive workflows into useful tools.</p><small>Ollama · Parsing · Data processing</small></div><div class="expertise-item"><div class="symbol">⌘</div><h3>Development workflow</h3><p>Working with tickets and Git branches, investigating bugs, writing tests and improving changes through code reviews.</p><small>Git · Debugging · Testing · Reviews</small></div></div></div></section>'''
about='''<section class="section"><div class="container about-block"><img class="portrait" src="@ROOT@assets/max.webp" width="600" height="645" loading="lazy" alt="Max Geurts"><div><div class="eyebrow">A little about me</div><h2>From game mechanics<br>to business logic.</h2><p>My background is in game development. Through internships and paid work at Xeropex, I discovered how much I enjoy building back-end systems that connect information and make practical work easier.</p><p>I'm looking for a team where I can contribute to a product over time, learn from experienced developers and keep improving the way I build software.</p><a class="link" href="@ROOT@about.html">More about me <span>↗</span></a></div></div></section>'''
games='<section class="section section-tight"><div class="container"><div class="section-head"><div><div class="eyebrow">Where it started</div><h2>Also built for play.</h2></div><a class="link" href="@ROOT@projects.html#game">Game development & earlier projects ↗</a></div><div class="game-strip">'+''.join(game_card(DATA[i]) for i in [5,7,9])+'</div></div></section>'
page('index.html','Junior Back-end Developer','Max Geurts: junior back-end developer with PHP, Laravel and Xeropex experience in business applications, automation and AI integrations.',hero+experience+featured+expertise+about+games+contact(),'Home')

for p in DATA:
 business=p['type']!='game'
 intro=f'<div class="container page-hero"><a class="breadcrumb" href="@ROOT@projects.html">← All projects</a><div class="eyebrow">{e(p["category"])}</div><h1>{e(p["title"])}</h1><p class="lead">{e(p["summary"])}</p></div>'
 aside=f'<aside class="case-aside"><dl><dt>Context</dt><dd>{"Xeropex / 2025–2026" if p["type"]=="business" or p["id"]=="bug-fixing" else "Personal portfolio" if p["id"]=="portfolio" else e(p["category"])}</dd><dt>Technology</dt><dd><div class="skill-list">{tags(p)}</div></dd><dt>Source</dt><dd>{"Private business code" if p["type"]=="business" or p["id"]=="bug-fixing" else "Public project" if p.get("repo") else "Portfolio case"}</dd></dl><nav aria-label="On this page"><a href="#role">My role</a><a href="#approach">Technical approach</a><a href="#result">Result</a><a href="#evidence">Demonstration & evidence</a></nav></aside>'
 sections=''
 if not business:sections+=f'<img class="large-image" src="@ROOT@assets/{p["image"]}" alt="Gameplay from {e(p["title"])}" width="1000" height="563">'
 for key,label in [('problem','The problem'),('role','My role'),('approach','Technical approach'),('challenge','Challenges & decisions'),('result','Result')]:
  if p.get(key):sections+=f'<section class="case-section" id="{key}"><h2>{label}</h2><p>{e(p[key])}</p></section>'
 if p.get('flow'):sections+='<section class="case-section"><h2>How the pieces connect</h2><ol class="flow">'+''.join(f'<li>{e(n)}</li>' for n in p['flow'])+'</ol><p class="caption">Simplified conceptual workflow. Not an exact internal architecture.</p></section>'
 sections+='<section class="case-section" id="evidence"><h2>Demonstration & evidence</h2>'
 if p.get('evidence'):sections+=f'<div class="notice">{e(p["evidence"])}</div>'
 if p['id'] in ['financial-dashboard','ai-chat','lead-generator']:sections+=visual(p)
 if p['id']=='lead-generator':sections+='<a class="btn primary" style="margin-top:25px" href="@ROOT@site/xeropexGeneratedSite.zip" download>Download example website ↓</a><p class="caption">28 HTML pages + assets · ZIP archive · prototype only</p>'
 if p.get('video'):sections+=f'<video class="case-video" controls playsinline preload="none" poster="@ROOT@assets/{p["image"]}"><source src="@ROOT@videos/{p["video"]}" type="video/mp4"><a href="@ROOT@videos/{p["video"]}">Download the demonstration video</a></video><p class="caption">Existing project footage from the original portfolio. {"Trailer of the complete team project." if p["id"]=="the-rift-guardian" else ""}</p>'
 if p.get('repo'):sections+=f'<a class="btn" style="margin-top:22px" href="{p["repo"]}">View project source on GitHub ↗</a>'
 if p['id']=='portfolio':sections+='<a class="btn" href="https://github.com/Mexwwww/portfolioFromMax">View original repository ↗</a>'
 sections+='</section><a class="link" href="@ROOT@projects.html">← Back to all projects</a>'
 page(p['path'],p['title'],p['summary'],intro+'<div class="container case-layout">'+aside+'<div>'+sections+'</div></div>'+contact(),'Projects')

def tile(p):
 image=f'<img class="tile-image" src="@ROOT@assets/{p["image"]}" alt="Gameplay from {e(p["title"])}" width="600" height="375" loading="lazy">' if p.get('image') else visual(p)
 return f'<article class="project-tile" data-category="{p["type"]}">{image}<div class="tile-content"><div class="number">{e(p["category"]).upper()}</div><h2><a href="@ROOT@{p["path"]}">{e(p["title"])}</a></h2><p>{e(p["summary"])}</p><div class="skill-list">{tags(p)}</div><a class="link" href="@ROOT@{p["path"]}">Explore project ↗</a></div></article>'
projects='<div class="container page-hero"><div class="eyebrow">The project archive</div><h1>Work, in more detail.</h1><p class="lead">Business software first. AI integrations, maintenance and game development along the way.</p></div><section class="container section section-tight"><div class="filter-bar" role="group" aria-label="Filter projects">'+''.join(f'<button class="filter" data-filter="{k}" aria-pressed="{str(k=="all").lower()}">{v}</button>' for k,v in [('all','All projects'),('business','Business & AI'),('software','Other software'),('game','Game development')])+'</div><p class="filter-status" role="status" aria-live="polite">10 projects shown</p><div class="project-grid">'+''.join(tile(p) for p in DATA)+'</div></section>'
page('projects.html','Projects','Explore Max Geurts’ work in Laravel business software, financial automation, local AI integration and game development.',projects+contact(),'Projects')
# Preserve category URLs with working HTML; legacy query parameters are handled by the filter enhancement.
for legacy in ['categories.html','categorisedProjects.html']:page(legacy,'Projects','Max Geurts’ software and game development projects.',projects+contact(),'Projects')

about_intro='<div class="container page-hero"><div class="eyebrow">About Max</div><h1>I like making the<br>pieces work together.</h1><p class="lead">A junior back-end developer from the Netherlands, with a game development background and practical experience in business software.</p></div>'
about_text='''<section class="container section section-tight two-col"><div><section class="about-section"><h2>How I got here</h2><p>During my Game Development education, I became increasingly interested in back-end systems, APIs and solving practical problems through software. That interest grew through internships and paid development work at Xeropex, where I worked with PHP and Laravel on existing applications and internal automation projects.</p><p>I enjoy building systems that connect information, automate repetitive tasks and make complex processes easier to manage. More recently, I've explored how local AI models can be integrated into applications through explicit back-end functions.</p></section><section class="about-section"><h2>What I'm looking for</h2><p>A junior back-end role in a collaborative development team, ideally working on one or a few larger products over time. I want to contribute, learn from experienced developers and develop my understanding of software architecture, integrations and dependable business software.</p><p>I'm available for 32 hours a week. I speak Dutch and English fluently.</p></section><section class="about-section"><h2>Experience & education</h2><div class="timeline-row"><small>2025 — 2026</small><div><h3>Xeropex</h3><p>Internships and paid back-end development work. Internal Laravel applications, existing customer software, API integrations, database design, debugging and team development workflows.</p></div></div><div class="timeline-row"><small>2022 — 2026</small><div><h3>Grafisch Lyceum Utrecht</h3><p>Game Development · Mbo level 4 · Completed.<br>A foundation in C#, Unity, problem solving and collaborative projects.</p></div></div></section><section class="about-section"><h2>Outside business software</h2><p>I still enjoy game development and exploring how interactive systems work. Experimenting with movement, mechanics and new tools is another way for me to keep learning.</p></section></div><div><img class="portrait" src="@ROOT@assets/max.webp" alt="Max Geurts" width="600" height="645"><div class="resume-preview" style="margin-top:25px"><div class="eyebrow">Core toolkit</div><div class="skill-list">'''+tags({'tech':['PHP','Laravel','MySQL / SQL','REST APIs','Filament','Ollama','Git','Docker','JavaScript / TypeScript']})+'''</div><p class="empty-note">Additional background: C#, Unity and Unreal Engine Blueprints.</p></div></div></section>'''
page('about.html','About','Meet Max Geurts: a Dutch junior back-end developer moving from game development into PHP, Laravel, business applications and AI integration.',about_intro+about_text+contact(),'About')
resume='''<div class="container page-hero"><div class="eyebrow">Resume</div><h1>The short version.</h1><p class="lead">My experience, education and main projects in one document.</p></div><section class="container section section-tight two-col"><div class="resume-preview"><div class="eyebrow">Software development · Dutch PDF</div><h2>Max Geurts</h2><p style="color:var(--accent);margin-top:10px">Junior Back-end Developer</p><ul><li>Practical PHP / Laravel experience at Xeropex</li><li>Financial automation and API integrations</li><li>Local AI chat and business reporting</li><li>Game Development · Mbo level 4 · Completed 2026</li></ul><div class="actions"><a class="btn primary" href="@ROOT@cv/Max-Geurts-Software-Development-NL.pdf" download>Download CV ↓</a><a class="btn" href="@ROOT@cv/Max-Geurts-Software-Development-NL.pdf">Open PDF ↗</a></div></div><div><h2>Looking for a junior developer?</h2><p>I'm interested in back-end and software development roles where I can contribute to a product and learn within an experienced team.</p><p>The case studies explain the context behind the projects in my CV, including what I built and the technical challenges involved.</p><div class="actions"><a class="btn" href="@ROOT@projects.html">Explore the projects ↗</a></div></div></section>'''
page('resume.html','Resume','Download Max Geurts’ current Dutch software development CV: junior back-end developer, PHP, Laravel and practical Xeropex experience.',resume+contact(),'Resume')
page('contact.html','Contact','Contact Max Geurts about junior PHP, Laravel and back-end development opportunities.',f'<div class="container page-hero"><div class="eyebrow">Contact</div><h1>Have a role in mind?</h1><p class="lead">Tell me about the product, the team and what you are looking for. Email is the easiest way to reach me.</p><div class="actions"><a class="btn primary" href="mailto:{EMAIL}">Email Max ↗</a><a class="btn" href="https://github.com/Mexwwww">View GitHub ↗</a></div></div>'+contact(),'Contact')
page('404.html','Page not found','This page could not be found. Explore Max Geurts’ developer portfolio.', '<div class="container page-hero"><div class="eyebrow">404 / Page not found</div><h1>Let’s get you back.</h1><p class="lead">The page may have moved. You can find all software and game projects in the project archive.</p><div class="actions"><a class="btn primary" href="@ROOT@projects.html">View all projects ↗</a><a class="btn" href="@ROOT@index.html">Home</a></div></div>')
# Keep the old CV URL valid, while serving the new software CV.
shutil.copy2(OUT/'cv/Max-Geurts-Software-Development-NL.pdf',OUT/'cv/CvOfMaxGeurts.pdf')
pages=['index.html','projects.html','about.html','resume.html','contact.html']+[p['path'] for p in DATA]
(OUT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{BASE+p}</loc></url>' for p in pages)+'</urlset>')
(OUT/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+BASE+'sitemap.xml\n')
print(f'Built {len(list(OUT.rglob("*.html")))} static HTML pages in {OUT}')
